size_t bt_c06_block_count(void){return sizeof(blocks)/sizeof(blocks[0]);}
size_t bt_c06_identity_count(void){return sizeof(identities)/sizeof(identities[0]);}
const bt_c06_block_meta *bt_c06_block_meta_at(uint32_t i){return i<bt_c06_block_count()?&blocks[i]:0;}
const bt_c06_identity_meta *bt_c06_identity_meta_at(uint32_t k){return (k>=1u&&k<=bt_c06_identity_count())?&identities[k-1u]:0;}
bt_aot_target_class bt_c06_classify_target(uint32_t i,uint16_t t){ if(i>=bt_c06_block_count())return BT_AOT_TARGET_INVALID; const bt_c06_block_meta*m=&blocks[i]; if(m->special_class!=BT_AOT_TARGET_INVALID)return m->special_class; for(uint16_t n=0;n<m->successor_count;n++){const bt_c06_successor*s=&successors[m->successor_offset+n];if(s->pc==t)return s->cls;} return BT_AOT_TARGET_TRAP;}
bt_aot_result bt_c06_execute_index(bt_aot_context *ctx,uint32_t i){
 bt_aot_result r={0};
 const bt_c06_block_meta *m;
 if(i>=bt_c06_block_count()){r.stop_reason=BT_AOT_STOP_TARGET_REJECTED;return r;}
 m=&blocks[i];
 r=bt_aot_execute_fixed(ctx,i,m->identity_key,m->pc,m->opcode);
 if(r.stop_reason!=BT_AOT_STOP_NONE)return r;
 if(m->opcode==0x20u){
  r=bt_aot_note_shadow_push(ctx,r,(uint16_t)(m->pc+m->length),BT_AOT_SHADOW_CALL);
  if(r.stop_reason!=BT_AOT_STOP_NONE)return r;
 }
 return bt_aot_finish_target(ctx,r,bt_c06_classify_target(i,r.next_pc));
}
int32_t bt_c06_find_block(uint32_t k,uint16_t pc){ uint32_t lo=0,hi=(uint32_t)bt_c06_block_count(); uint32_t want=(k<<16)|pc; while(lo<hi){uint32_t m=lo+(hi-lo)/2u;uint32_t got=(blocks[m].identity_key<<16)|blocks[m].pc;if(got<want)lo=m+1u;else hi=m;} if(lo<bt_c06_block_count()&&blocks[lo].identity_key==k&&blocks[lo].pc==pc)return (int32_t)lo;return -1;}
